/// Non-secret, build-time environment configuration.
///
/// This file deliberately contains no API keys, service account credentials,
/// or other secrets. Sensitive Firebase configuration lives in
/// `lib/app/firebase_options.dart`, which is generated by the FlutterFire CLI
/// and must never be committed to a public repository.
abstract final class Env {
  /// Human readable environment name shown in debug builds.
  static const String environment = 'development';

  /// Whether the app is running in a release build (AOT compiled).
  static bool get isRelease => const bool.fromEnvironment('dart.vm.product');

  /// Cloudinary account used for all binary media (images, videos, documents).
  static const String cloudinaryCloudName = 'wsc91vuk';

  /// Unsigned Cloudinary upload preset used for media uploads.
  static const String cloudinaryUploadPreset = 'Images Acaderix';
}
